class ItineraryActivity { const ItineraryActivity({required this.id,required this.title,required this.durationMinutes,this.priority=0,this.mustDo=false}); final String id,title; final int durationMinutes,priority; final bool mustDo; }
class ItineraryPlan { const ItineraryPlan(this.scheduled,this.unscheduled,this.usedMinutes); final List<ItineraryActivity> scheduled,unscheduled; final int usedMinutes; }
class ItineraryPlanner { const ItineraryPlanner(); ItineraryPlan plan(Iterable<ItineraryActivity> items,{required int availableMinutes}){if(availableMinutes<0)throw ArgumentError.value(availableMinutes);final seen=<String>{};final valid=<ItineraryActivity>[];final invalid=<ItineraryActivity>[];for(final item in items){if(item.id.trim().isEmpty||item.id!=item.id.trim()||item.title.trim().isEmpty||item.durationMinutes<=0||!seen.add(item.id)){invalid.add(item);}else{valid.add(item);}}valid.sort((a,b){final m=(b.mustDo?1:0).compareTo(a.mustDo?1:0);if(m!=0)return m;final p=b.priority.compareTo(a.priority);return p!=0?p:a.id.compareTo(b.id);});final yes=<ItineraryActivity>[],no=<ItineraryActivity>[...invalid];var used=0;for(final a in valid){if(used+a.durationMinutes<=availableMinutes){yes.add(a);used+=a.durationMinutes;}else{no.add(a);}}return ItineraryPlan(List.unmodifiable(yes),List.unmodifiable(no),used);}}
